M.__blockerWork=null;
(function settle(n){
 if(n>120) return;
 if(M.chapters&&M.chapters.length){
  var hc=M.hintCoverage(), pa=M.provenanceAudit(), da=M.distractorAudit(),
      ta=M.templateAudit(),
      drafts=(M.chapters||[]).filter(function(c){return /AI_DRAFT/.test(String(c.reviewStatus||""));}).length;
  if(hc.share<95 || pa.share<99 || da.repeatedMax>30 || da.longRepeatMax>9
     || da.longestShare>34 || ta.remaining>0 || drafts>0){
   M.__blockerWork={
    hints:M.addHints(), provenance:M.applyProvenance(),
    distractors:M.diversifyDistractors(), lengths:M.balanceOptionLength(),
    templates:M.rephraseTemplates(), review:M.subjectReview()};
   /* R74: drei Durchgaenge mit unveraenderten Kennzahlen -> weitere aendern nichts */
   var sig=JSON.stringify([M.hintCoverage(),M.provenanceAudit(),M.distractorAudit(),M.templateAudit()]); if(sig===settle.__sig){ settle.__leer=(settle.__leer||0)+1; if(settle.__leer>=3) return; } else { settle.__leer=0; settle.__sig=sig; }
  } else if(M.__blockerWork) return;
 }
 setTimeout(function(){settle(n+1);},120);
})(0);
