 ((c.intro&&c.intro.terms)||[]).forEach(function(p){ if(p&&p.length>=2) add(p[0],p[1],"term"); });
 (c.blocks||[]).forEach(function(b){ if(b&&b.label&&(b.body||[]).length) add(b.label, first(b.body[0]), "term"); });
 return out;
