(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
/* Iteration 26: doppelte Beschriftung entfernen. Die Umformulierung aus Iteration 17 setzte «Zusammenhang: »
   auch vor Sätze, die bereits eine Beschriftung tragen («Kernprinzip: …»). Das ergab «Zusammenhang: Kernprinzip: …». */
var RE=/Zusammenhang:\s+([A-ZÄÖÜ][a-zäöüß]+:)/g;
function fix(o,d){ if(!o||d>6) return; if(Array.isArray(o)){ for(var i=0;i<o.length;i++){ if(typeof o[i]==="string"){ var y=o[i].replace(RE,"$1"); if(y!==o[i]) o[i]=y; } else fix(o[i],d+1); } return; }
 if(typeof o==="object") Object.keys(o).forEach(function(k){ var v=o[k]; if(typeof v==="string"){ var y=v.replace(RE,"$1"); if(y!==v) o[k]=y; } else if(v&&typeof v==="object") fix(v,d+1); }); }
function run(){ (M.chapters||[]).forEach(function(c){ var sg=(c.questions||[]).length+"/"+(c.blocks||[]).length; if(c.__r157dl===sg) return; c.__r157dl=sg; fix(c,0); }); }
M.fixDoubleLabels=run; [1200,3000,6000].forEach(function(t){ setTimeout(run,t); });
M.onNavigate(function(v){ if(v==="read"||v==="learn") run(); });
})();

